mapper.update:
UPDATE SYM0YA
   SET JM_NM       = #{jmNm, jdbcType=VARCHAR}
     , SEQ_NO      = #{seqNo, jdbcType=NUMERIC}
     , BALH_NATION = #{balhNation, jdbcType=VARCHAR}
     , CURRENCY    = #{currency, jdbcType=VARCHAR}
     , IJA_PER     = #{ijaPer, jdbcType=NUMERIC}
     , BALH_YMD    = CASE WHEN #{balhYmd, jdbcType=VARCHAR} IS NOT NULL AND TRIM(#{balhYmd, jdbcType=VARCHAR}) != ''
                          THEN TO_DATE(SUBSTR(REGEXP_REPLACE(#{balhYmd, jdbcType=VARCHAR}, '[^0-9]', ''), 1, 8), 'YYYYMMDD')
                          ELSE NULL END
     , SANGHW_YMD  = CASE WHEN #{sanghwYmd, jdbcType=VARCHAR} IS NOT NULL AND TRIM(#{sanghwYmd, jdbcType=VARCHAR}) != ''
                          THEN TO_DATE(SUBSTR(REGEXP_REPLACE(#{sanghwYmd, jdbcType=VARCHAR}, '[^0-9]', ''), 1, 8), 'YYYYMMDD')
                          ELSE NULL END
     , GYULJE_JM   = COALESCE(#{gyuljeJm, jdbcType=VARCHAR}, 'N')
     , JASAN_ATTR  = #{jasanAttr, jdbcType=VARCHAR}
     , SEDOL       = #{sedol, jdbcType=VARCHAR}
 WHERE CORP_GR  = #{corpGr}
   AND JM_CD    = #{jmCd}
   AND JASAN_GB = COALESCE(#{jasanGb, jdbcType=VARCHAR}, '5')

mapper.delete:
